<?php
declare(strict_types=1);session_start();require dirname(__DIR__).'/config/config.php';require_sign_in();
$role=(string)($_SESSION['role']??'');$uid=(int)$_SESSION['user_id'];$leadership=['director','sub_director','headteacher','head_academic'];$canEdit=in_array($role,$leadership,true);$pupils=[];$schools=[];$school=0;$pupilId=0;
if($role==='parent'){$q=db()->prepare("SELECT p.id,p.first_name,p.last_name,p.class_level,p.school_id,s.name school_name FROM pupil_guardians g JOIN pupils p ON p.id=g.pupil_id AND p.school_id=g.school_id JOIN schools s ON s.id=p.school_id WHERE g.guardian_user_id=? AND p.status='active' ORDER BY s.name,p.last_name,p.first_name");$q->execute([$uid]);$pupils=$q->fetchAll();$pupilId=(int)($_GET['pupil_id']??($pupils[0]['id']??0));if(!array_filter($pupils,fn($p)=>(int)$p['id']===$pupilId))$pupilId=(int)($pupils[0]['id']??0);}elseif(!in_array($role,['pupil','teacher',...$leadership],true)){http_response_code(403);exit('Your role cannot view a timetable.');}else{if($role==='teacher'||$canEdit){$q=db()->prepare('SELECT s.id,s.name FROM schools s JOIN school_memberships m ON m.school_id=s.id WHERE m.user_id=? ORDER BY s.name');$q->execute([$uid]);$schools=$q->fetchAll();$ids=array_map('intval',array_column($schools,'id'));$requested=(int)($_GET['school_id']??($ids[0]??0));$school=in_array($requested,$ids,true)?$requested:0;}}
$csrf=csrf_token();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Timetable · ShuleLite</title><link rel="stylesheet" href="assets/app.css"><script defer src="assets/app.js"></script><script defer src="assets/timetable.js"></script></head><body><div class="app-shell"><?php require __DIR__.'/sidebar.php';?><main class="main-area"><header class="topbar"><button class="icon-button menu-toggle" data-menu aria-label="Open navigation" aria-expanded="false">☰</button><div class="crumb">School day <span>/</span> Timetable</div><div class="top-actions"><span class="role-chip"><?=e(str_replace('_',' ',$role))?></span></div></header><div class="page-content" data-timetable data-api="api/timetable.php" data-role="<?=e($role)?>" data-school="<?=$school?>" data-pupil="<?=$pupilId?>" data-csrf="<?=e($csrf)?>"><section class="welcome-row"><div><div class="eyebrow">WEEKLY SCHEDULE</div><h1>Timetable</h1><p class="muted">Published weekly class periods and assigned teachers.</p></div><?php if($role==='parent'):?><form method="get"><label for="timetable-pupil">Child</label><select id="timetable-pupil" name="pupil_id" onchange="this.form.submit()"><?php foreach($pupils as $p):?><option value="<?=$p['id']?>"<?=(int)$p['id']===$pupilId?' selected':''?>><?=e($p['first_name'].' '.$p['last_name'].' · '.$p['school_name'])?></option><?php endforeach;?></select></form><?php elseif($schools&&count($schools)>1):?><form method="get"><label for="timetable-school">School</label><select id="timetable-school" name="school_id" onchange="this.form.submit()"><?php foreach($schools as $s):?><option value="<?=$s['id']?>"<?=(int)$s['id']===$school?' selected':''?>><?=e($s['name'])?></option><?php endforeach;?></select></form><?php endif;?></section><?php if(($role==='parent'&&!$pupils)||(($role==='teacher'||$canEdit)&&!$school)):?><div class="empty-state"><h2>No linked pupil or school</h2><p>Ask your school to link your account to an active record.</p></div><?php else:?><div data-timetable-status class="notice" role="status" aria-live="polite" hidden></div><?php if($canEdit):?><section class="note-create"><div class="section-heading"><h2>Add a timetable period</h2></div><form data-timetable-form class="note-form"><div class="form-grid"><div><label for="tt-class">Class</label><select id="tt-class" name="class_id" required></select></div><div><label for="tt-stream">Stream</label><select id="tt-stream" name="stream_id"><option value="">All streams</option></select></div><div><label for="tt-subject">Subject</label><select id="tt-subject" name="subject_id" required></select></div><div><label for="tt-teacher">Teacher</label><select id="tt-teacher" name="teacher_id" required></select></div><div><label for="tt-day">Day</label><select id="tt-day" name="day_of_week" required><option value="1">Monday</option><option value="2">Tuesday</option><option value="3">Wednesday</option><option value="4">Thursday</option><option value="5">Friday</option><option value="6">Saturday</option><option value="7">Sunday</option></select></div><div><label for="tt-start">Starts</label><input id="tt-start" name="starts_at" type="time" required></div><div><label for="tt-end">Ends</label><input id="tt-end" name="ends_at" type="time" required></div><div><label for="tt-room">Room (optional)</label><input id="tt-room" name="room" maxlength="80"></div></div><div class="planning-actions"><button class="button" name="status" value="draft">Save draft</button><button class="button primary" name="status" value="published">Publish period</button></div></form></section><?php endif;?><section class="content-section"><div class="section-heading"><h2>Weekly periods</h2><button type="button" class="button" data-timetable-refresh>Refresh</button></div><div class="table-wrap" data-timetable-list><p class="muted">Loading timetable…</p></div></section><?php endif;?><footer class="page-footer">ShuleLite · Timetable</footer></div></main></div></div></body></html>
